    "const ST = {\n",
    "AL:{n:\"Alabama\",cap:\"Montgomery\",big:\"Huntsville\",adm:\"December 14, 1819\",ord:22,pop:5193088,pr:24,area:52420,ar:30,nick:\"Yellowhammer State\",reg:\"South\",div:\"East South Central\",tz:\"Central\",\n",
    " hi:[\"Cheaha Mountain\",2413],lo:[\"Gulf of Mexico\",0],np:[],\n",
    " geo:\"Southern terminus of the Appalachians in the northeast, giving way to the Piedmont, then the Black Belt prairie and the Gulf Coastal Plain. Mobile Bay is the state's only deep-water port and drains a basin covering most of the state.\",\n",
    " feat:[\"Cheaha Mountain\",\"Mobile Bay & Delta\",\"Little River Canyon\",\"Cathedral Caverns\",\"Wheeler Lake\"],\n",
    " riv:[\"Tennessee\",\"Alabama\",\"Tombigbee\",\"Chattahoochee\",\"Mobile\"],rng:[\"Appalachian foothills\",\"Talladega Mountains\"],\n",
    " cty:[\"Huntsville\",\"Birmingham\",\"Montgomery\",\"Mobile\",\"Tuscaloosa\"],\n",
    " econ:\"Aerospace and defense at Huntsville, automotive assembly (Mercedes, Hyundai, Honda), steel at Birmingham, forestry, and the Port of Mobile.\",\n",
    " hist:\"Ceded by France and Spain, admitted 1819. Montgomery was the first capital of the Confederacy in 1861. Selma and Montgomery were central to the civil rights movement of 1955-1965.\"},\n",
    "\n",
    "AK:{n:\"Alaska\",cap:\"Juneau\",big:\"Anchorage\",adm:\"January 3, 1959\",ord:49,pop:737270,pr:48,area:665384,ar:1,nick:\"The Last Frontier\",reg:\"West\",div:\"Pacific\",tz:\"Alaska / Hawaii-Aleutian\",\n",
