    "DE:{n:\"Delaware\",cap:\"Dover\",big:\"Wilmington\",adm:\"December 7, 1787\",ord:1,pop:1059952,pr:45,area:2489,ar:49,nick:\"The First State\",reg:\"South\",div:\"South Atlantic\",tz:\"Eastern\",\n",
