    "FL:{n:\"Florida\",cap:\"Tallahassee\",big:\"Jacksonville\",adm:\"March 3, 1845\",ord:27,pop:23462518,pr:3,area:65758,ar:22,nick:\"Sunshine State\",reg:\"South\",div:\"South Atlantic\",tz:\"Eastern / Central (western panhandle)\",\n",
