    "GA:{n:\"Georgia\",cap:\"Atlanta\",big:\"Atlanta\",adm:\"January 2, 1788\",ord:4,pop:11302748,pr:8,area:59425,ar:24,nick:\"Peach State\",reg:\"South\",div:\"South Atlantic\",tz:\"Eastern\",\n",
