    " feat:[\"Loess Hills\",\"Effigy Mounds\",\"Driftless Area bluffs\",\"Okoboji lakes\"],\n",
    " riv:[\"Mississippi\",\"Missouri\",\"Des Moines\",\"Cedar\"],rng:[],\n",
    " cty:[\"Des Moines\",\"Cedar Rapids\",\"Davenport\",\"Sioux City\",\"Iowa City\"],\n",
    " econ:\"Leading producer of corn, soybeans, pork and eggs. Insurance at Des Moines, wind power (a large share of in-state generation), and ethanol.\",\n",
    " hist:\"Part of the Louisiana Purchase, admitted 1846. Its presidential caucuses opened the nominating calendar from 1972 through 2020.\"},\n",
    "\n",
    "KS:{n:\"Kansas\",cap:\"Topeka\",big:\"Wichita\",adm:\"January 29, 1861\",ord:34,pop:2977220,pr:34,area:82278,ar:15,nick:\"Sunflower State\",reg:\"Midwest\",div:\"West North Central\",tz:\"Central / Mountain (four western counties)\",\n",
