    "\n",
    "KY:{n:\"Kentucky\",cap:\"Frankfort\",big:\"Louisville\",adm:\"June 1, 1792\",ord:15,pop:4606864,pr:26,area:40408,ar:37,nick:\"Bluegrass State\",reg:\"South\",div:\"East South Central\",tz:\"Eastern / Central (western half)\",\n",
