    "ME:{n:\"Maine\",cap:\"Augusta\",big:\"Portland\",adm:\"March 15, 1820\",ord:23,pop:1414874,pr:42,area:35380,ar:39,nick:\"Pine Tree State\",reg:\"Northeast\",div:\"New England\",tz:\"Eastern\",\n",
