    "\n",
    "MD:{n:\"Maryland\",cap:\"Annapolis\",big:\"Baltimore\",adm:\"April 28, 1788\",ord:7,pop:6265347,pr:19,area:12406,ar:42,nick:\"Old Line State\",reg:\"South\",div:\"South Atlantic\",tz:\"Eastern\",\n",
