    "MA:{n:\"Massachusetts\",cap:\"Boston\",big:\"Boston\",adm:\"February 6, 1788\",ord:6,pop:7154084,pr:16,area:10554,ar:44,nick:\"Bay State\",reg:\"Northeast\",div:\"New England\",tz:\"Eastern\",\n",
