    "\n",
    "MI:{n:\"Michigan\",cap:\"Lansing\",big:\"Detroit\",adm:\"January 26, 1837\",ord:26,pop:10127884,pr:10,area:96714,ar:11,nick:\"Great Lakes State\",reg:\"Midwest\",div:\"East North Central\",tz:\"Eastern / Central (four western Upper Peninsula counties)\",\n",
    " hi:[\"Mount Arvon\",1979],lo:[\"Lake Erie\",571],np:[\"Isle Royale\"],\n",
    " geo:\"Two peninsulas separated by the Straits of Mackinac, touching four of the five Great Lakes. The longest freshwater coastline of any political subdivision on earth, some 3,200 miles. No point is more than 85 miles from a Great Lake.\",\n",
