    "\n",
    "MT:{n:\"Montana\",cap:\"Helena\",big:\"Billings\",adm:\"November 8, 1889\",ord:41,pop:1144694,pr:43,area:147040,ar:4,nick:\"Treasure State\",reg:\"West\",div:\"Mountain\",tz:\"Mountain\",\n",
    " hi:[\"Granite Peak\",12807],lo:[\"Kootenai River\",1800],np:[\"Glacier\"],\n",
