    "\n",
    "SC:{n:\"South Carolina\",cap:\"Columbia\",big:\"Charleston\",adm:\"May 23, 1788\",ord:8,pop:5570274,pr:23,area:32020,ar:40,nick:\"Palmetto State\",reg:\"South\",div:\"South Atlantic\",tz:\"Eastern\",\n",
