    "\n",
    "WY:{n:\"Wyoming\",cap:\"Cheyenne\",big:\"Cheyenne\",adm:\"July 10, 1890\",ord:44,pop:588753,pr:51,area:97813,ar:10,nick:\"Equality State\",reg:\"West\",div:\"Mountain\",tz:\"Mountain\",\n",
