    "\n",
    "DC:{n:\"District of Columbia\",cap:\"Federal capital\",big:\"Washington\",adm:\"Established July 16, 1790; seat of government from 1800\",ord:0,pop:693645,pr:49,area:68,ar:51,nick:\"The District\",reg:\"South (Census classification)\",div:\"South Atlantic\",tz:\"Eastern\",\n",
