    " 'West South Central':'西南中部','South Atlantic':'南大西洋','New England':'ニューイングランド',\n",
    " 'East North Central':'東北中部','West North Central':'西北中部','Middle Atlantic':'中部大西洋'};\n",
    "function regOf(c){var s=ST[c];\n",
    "  if(cur==='zh') return (REGZH[s.reg]||s.reg)+' \\u00B7 '+(DIVZH[s.div]||s.div);\n",
    "  if(cur==='ja') return (REGJA[s.reg]||s.reg)+' \\u00B7 '+(DIVJA[s.div]||s.div);\n",
    "  return s.reg+' \\u00B7 '+s.div;}\n",
    "function tzOf(c){var s=ST[c];return cur==='zh'?(TZZH[s.tz]||s.tz):s.tz;}\n",
    "var MON={January:1,February:2,March:3,April:4,May:5,June:6,July:7,August:8,\n",
    "  September:9,October:10,November:11,December:12};\n",
    "function dateT(s){\n",
    "  if(cur==='en') return s;\n",
    "  return s.replace(/([A-Z][a-z]+) (\\d{1,2}), (\\d{4})/g,function(m,mo,d,y){\n",
    "    return MON[mo]?(y+'年'+MON[mo]+'月'+d+'日'):m;});\n",
