    "/* derived per-state fields */\n",
    "CODES.forEach(function(c){var s=ST[c];\n",
    "  s.code=c; s.den=s.pop/s.area; s.hiv=s.hi[1]; s.npn=s.np.length;\n",
    "  var m=s.adm.match(/(\\d{4})/); s.admy=m?+m[1]:1790;\n",
    "  var e=EXT[c]||[0,0,0,'']; s.seats=e[0]; s.ev=e[1]; s.ncnty=e[2];\n",
    "  s.perSeat=s.seats?Math.round(s.pop/s.seats):0;\n",
    "});\n",
    "\n",
    "/* ------------------------------------------------------------ projection ---\n",
    "   d3.geoAlbersUsa at the scale and translation used by us-atlas, so that\n",
    "   fetched surveyed geometry, already projected into a 975x610 frame, and the\n",
    "   built-in lon/lat outline coincide exactly. y is negated on the way out,\n",
    "   which is what SVG requires. */\n",
    "var RAD=Math.PI/180;\n",
    "function conicRaw(p0,p1){\n",
    "  var s0=Math.sin(p0*RAD), n=(s0+Math.sin(p1*RAD))/2;\n",
    "  var c=1+s0*(2*n-s0), r0=Math.sqrt(c)/n;\n",
    "  return function(lam,phi){\n",
    "    var r=Math.sqrt(Math.max(c-2*n*Math.sin(phi),0))/n, x=lam*n;\n",
    "    return [r*Math.sin(x), r0-r*Math.cos(x)];\n",
    "  };\n",
    "}\n",
    "function mkSub(par,rot,ctr,k,tx,ty){\n",
    "  var raw=conicRaw(par[0],par[1]), c=raw(ctr[0]*RAD,ctr[1]*RAD);\n",
    "  var dx=tx-k*c[0], dy=ty+k*c[1];\n",
    "  var f=function(lon,lat){\n",
    "    var lam=(lon+rot)*RAD;\n",
    "    while(lam>Math.PI) lam-=2*Math.PI;\n",
    "    while(lam<-Math.PI) lam+=2*Math.PI;\n",
    "    var p=raw(lam,lat*RAD);\n",
    "    return [dx+k*p[0], dy-k*p[1]];\n",
    "  };\n",
    "  f.k=k; return f;\n",
    "}\n",
    "/* Each frame is fitted to its box: project once at unit scale, measure, then\n",
    "   choose the scale and offset that centre the subject. Nothing is hand tuned,\n",
    "   so the boxes can be rearranged freely. */\n",
    "function fitSub(par,rot,ctr,pts,box,pad){\n",
    "  function span(f){\n",
    "    var x0=1e9,y0=1e9,x1=-1e9,y1=-1e9;\n",
    "    for(var i=0;i<pts.length;i++){\n",
    "      var q=f(pts[i][0],pts[i][1]);\n",
    "      if(q[0]<x0)x0=q[0]; if(q[0]>x1)x1=q[0];\n",
    "      if(q[1]<y0)y0=q[1]; if(q[1]>y1)y1=q[1];\n",
    "    }\n",
    "    return [x0,y0,x1-x0,y1-y0];\n",
    "  }\n",
    "  var probe=mkSub(par,rot,ctr,1000,0,0), s1=span(probe);\n",
    "  var k=1000*Math.min((box[2]-2*pad)/Math.max(s1[2],1e-6),\n",
    "                      (box[3]-2*pad)/Math.max(s1[3],1e-6));\n",
    "  var f2=mkSub(par,rot,ctr,k,0,0), s2=span(f2);\n",
    "  return mkSub(par,rot,ctr,k,\n",
    "    box[0]+box[2]/2-(s2[0]+s2[2]/2),\n",
    "    box[1]+box[3]/2-(s2[1]+s2[3]/2));\n",
    "}\n",
    "var SHEET=[0,0,975,772];\n",
    "var BOX={main:[14,8,947,510], AK:[14,532,236,168], HI:[258,532,168,168],\n",
    "         PR:[434,532,178,168], GU:[620,532,148,168], AS:[776,532,185,168]};\n",
    "function zoneOf(lon,lat){\n",
    "  if(lat<0) return 5;                                        /* American Samoa */\n",
    "  if(lon>140) return 4;                                      /* Guam, Marianas */\n",
    "  if(lat>50&&lon<-128) return 1;                             /* Alaska */\n",
    "  if(lon>-161.6&&lon<-153.4&&lat>17.5&&lat<23.6) return 2;   /* Hawaii */\n",
    "  if(lon>-68.6&&lat<19.6) return 3;                          /* Puerto Rico, USVI */\n",
    "  return 0;\n",
    "}\n",
    "var ZKEY=['main','AK','HI','PR','GU','AS'];\n",
    "(function(){\n",
    "  var pool=[[],[],[],[],[],[]];\n",
    "  function add(rings){ rings.forEach(function(r){\n",
    "      var z=zoneOf(r[0][0],r[0][1]);\n",
    "      for(var i=0;i<r.length;i+=Math.max(1,Math.floor(r.length/40))) pool[z].push(r[i]);\n",
    "      pool[z].push(r[r.length-1]);\n",
    "    });}\n",
    "  Object.keys(GEO.states).forEach(function(c){add(GEO.states[c]);});\n",
    "  Object.keys(GEO.terr).forEach(function(c){add(GEO.terr[c]);});\n",
    "  window.__pool=pool;\n",
    "})();\n",
    "var SUBS=[\n",
    "  fitSub([29.5,45.5],96,[-0.6,38.7],window.__pool[0],BOX.main,6),\n",
    "  fitSub([55,65],154,[-2,58.5],window.__pool[1],BOX.AK,9),\n",
    "  fitSub([8,18],157,[-3,19.9],window.__pool[2],BOX.HI,9),\n",
    "  fitSub([17.5,18.6],66,[0,18.2],window.__pool[3],BOX.PR,9),\n",
