    "CODES.forEach(function(c){ if(GEO.states[c]) SCHEM[c]=pathOf(GEO.states[c],true); });\n",
    "var TPATH={}; Object.keys(GEO.terr).forEach(function(k){TPATH[k]=pathOf(GEO.terr[k],true);});\n",
    "\n",
    "var ANCHOR={MI:[-84.7,43.4],FL:[-81.5,28.4],LA:[-92.4,31.3],MD:[-77.0,39.45],VA:[-78.6,37.5],\n",
    " MA:[-71.9,42.32],NY:[-75.4,43.0],CA:[-119.6,37.1],TX:[-99.4,31.3],ID:[-114.6,44.4],\n",
    " MN:[-94.4,46.4],NJ:[-74.65,40.15],DE:[-75.42,38.95],RI:[-71.58,41.72],CT:[-72.7,41.62],\n",
    " NH:[-71.6,43.8],VT:[-72.72,44.1],WV:[-80.4,38.7],ME:[-69.2,45.3],HI:[-156.3,20.4],\n",
    " AK:[-152.5,63.8],WA:[-120.4,47.3],OK:[-97.6,35.6],TN:[-86.3,35.8],KY:[-85.4,37.5],\n",
    " NC:[-79.3,35.5],SC:[-80.9,33.9],AL:[-86.8,32.8],MS:[-89.7,32.7],GA:[-83.4,32.7]};\n",
    "\n",
    "function drawStates(src){\n",
    "  L.states.textContent=''; L.coast.textContent=''; paths={};\n",
    "  var all='';\n",
    "  CODES.forEach(function(c){\n",
    "    var d=src[c]; if(!d) return;\n",
