    "/* A 68 square mile district is a fraction of a pixel at sheet scale. Anything\n",
    "   that small gets an invisible target of constant screen size so it can be\n",
    "   picked at all. */\n",
    "function buildHitTargets(){\n",
    "  if(!L.hit) return;\n",
    "  L.hit.textContent='';\n",
    "  var all={}; Object.keys(paths).forEach(function(c){all[c]=1;});\n",
    "  Object.keys(tpaths).forEach(function(c){all[c]=1;});\n",
    "  Object.keys(all).forEach(function(c){\n",
    "    var b=bbox[c]; if(!b) return;\n",
    "    if(Math.max(b[2],b[3])>=13) return;\n",
    "    var a=ANCHOR[c], x, y;\n",
    "    if(a){var q=proj(a[0],a[1]); x=q.p[0]; y=q.p[1];}\n",
    "    else {x=b[0]+b[2]/2; y=b[1]+b[3]/2;}\n",
    "    var g=el('g',{transform:'translate('+x.toFixed(1)+' '+y.toFixed(1)+')'});\n",
    "    var inner=el('g',{'class':'mk'});\n",
    "    var ci=el('circle',{cx:0,cy:0,r:6.5,fill:'transparent','pointer-events':'all'});\n",
    "    if(ST[c]) ci.setAttribute('data-c',c); else ci.setAttribute('data-t2',c);\n",
    "    ci.setAttribute('aria-hidden','true');\n",
    "    inner.appendChild(ci); g.appendChild(inner); L.hit.appendChild(g);\n",
    "  });\n",
    "}\n",
    "\n",
    "/* graticule */\n",
    "(function(){\n",
    "  var lines=[], f=SUBS[0];\n",
    "  for(var lon=-125;lon<=-65;lon+=10){\n",
    "    var a=[]; for(var la=24;la<=50;la+=0.5) a.push(f(lon,la)); lines.push(a);\n",
    "  }\n",
    "  for(var lat=25;lat<=50;lat+=5){\n",
