    "  }\n",
    "  lines.forEach(function(pts){\n",
    "    L.grat.appendChild(el('path',{d:dOf(pts,false),'class':'grat'}));\n",
    "  });\n",
    "})();\n",
    "\n",
    "/* water. Great Lakes sit between the states, so they go under the land. */\n",
    "var OPENW={'Lake Superior':1,'Lake Michigan':1,'Lake Huron':1,'Lake Erie':1,\n",
