    "     '<b>メイン州</b>\\u00a0<span class=\"mono\">約89%</span>']],\n",
    "   [['Longest coastline','海岸線最長','海岸線最長'],\n",
    "    ['<b>Alaska</b>\\u00a0<span class=\"mono\">33,900\\u00a0mi</span>',\n",
