    "    ['<b>Michigan</b>\\u00a0<span class=\"mono\">c.\\u00a03,200\\u00a0mi</span>',\n",
    "     '<b>密西根州</b>\\u00a0<span class=\"mono\">約3,200英里</span>',\n",
    "     '<b>ミシガン州</b>\\u00a0<span class=\"mono\">約3,200マイル</span>']],\n",
    "   [['Only state draining to three seas','唯一分流三大水域者','三つの海に注ぐ唯一の州'],\n",
    "    ['<b>Minnesota</b>','<b>明尼蘇達州</b>','<b>ミネソタ州</b>']],\n",
