    "     '<b>カリフォルニア州</b>\\u00a0<span class=\"mono\">9</span>']],\n",
    "   [['States with no national park','無國家公園的州','国立公園のない州'],\n",
    "    ['<b>20</b>','<b>20</b>','<b>20</b>']],\n",
