    " [1941,0,['Pearl Harbor attacked; entry into the Second World War',\n",
    "   '珍珠港遇襲，參加第二次世界大戰','真珠湾攻撃、第二次世界大戦参戦'],'7 December'],\n",
    " [1945,0,['War ends; the United Nations Charter is signed at San Francisco',\n",
    "   '大戰結束，聯合國憲章於舊金山簽署','終戦、サンフランシスコで国連憲章に署名'],'June, September'],\n",
    " [1954,0,['Brown v. Board of Education ends segregation in public schools in law',\n",
    "   '布朗訴教育局案於法律上終結公立學校種族隔離','ブラウン判決、公立学校の人種隔離を法的に終結'],'Supreme Court'],\n",
    " [1959,1,['Alaska and Hawaii admitted as the forty-ninth and fiftieth states',\n",
    "   '阿拉斯加與夏威夷成為第四十九與第五十州','アラスカとハワイが49・50番目の州に'],'January, August'],\n",
    " [1964,0,['Civil Rights Act; the Voting Rights Act follows in 1965',\n",
    "   '民權法案通過，1965年再通過投票權法案','公民権法成立、翌1965年に投票権法'],'July'],\n",
    " [1969,0,['Apollo 11 lands on the Moon','阿波羅十一號登陸月球','アポロ11号が月面着陸'],'20 July'],\n",
    " [1991,0,['The Cold War ends with the dissolution of the Soviet Union',\n",
    "   '蘇聯解體，冷戰結束','ソ連崩壊により冷戦終結'],'December'],\n",
